
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_tw3_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_tw3", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.447520802284045e+01, 9.081519361447914e+01, 8.581018375218741e+01, 7.911520534510741e+01, 7.043772364521229e+01, 5.968504586611275e+01, 4.718274958297262e+01, 3.388812635799215e+01, 2.138963092125772e+01, 1.142124785966423e+01, 5.054569689784607e+00, 2.542548149315708e+00, 1.914165305705857e+00, 1.274373309105332e+00, 6.457785859526424e-01, 2.428346680084710e-01, 6.128697669904135e-02, 7.605224674792504e-03, 3.526305943033466e-04, 4.424464024847697e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


